import web
from openlibrary.core.db import get_db
from openlibrary.core.bookshelves import Bookshelves
from openlibrary.core.booknotes import Booknotes

class TestUpdateWorkID:

    @classmethod
    def setup_class(cls):
        web.config.db_parameters = dict(dbn="sqlite", db=":memory:")
        db = get_db()
        db.query("""
        CREATE TABLE bookshelves_books (
        username text NOT NULL,
        work_id integer NOT NULL,
        bookshelf_id INTEGER references bookshelves(id) ON DELETE CASCADE ON UPDATE CASCADE,
        edition_id integer default null,
        primary key (username, work_id, bookshelf_id)
        );
        """)

    def setup_method(self, method):
        self.db = get_db()
        self.source_book = {
            "username": "@cdrini",
            "work_id": "1",
            "edition_id": "1",
            "bookshelf_id": "1"
        }
        assert not len(list(self.db.select("bookshelves_books")))
        self.db.insert("bookshelves_books", **self.source_book)

    def teardown_method(self):
        self.db.query("delete from bookshelves_books;")

    def test_update_collision(self):
        existing_book = {
            "username": "@cdrini",
            "work_id": "2",
            "edition_id": "2",
            "bookshelf_id": "1"
        }
        self.db.insert("bookshelves_books", **existing_book)
        assert len(list(self.db.select("bookshelves_books"))) == 2
        Bookshelves.update_work_id(self.source_book['work_id'], existing_book['work_id'])
        assert len(list(self.db.select("bookshelves_books", where={
            "username": "@cdrini",
            "work_id": "2",
            "edition_id": "2"
        }))), "failed to update 1 to 2"
        assert not len(list(self.db.select("bookshelves_books", where={
            "username": "@cdrini",
            "work_id": "1",
            "edition_id": "1"
        }))), "old work_id 1 present"


    def test_update_simple(self):
        assert len(list(self.db.select("bookshelves_books"))) == 1
        Bookshelves.update_work_id(self.source_book['work_id'], "2")
        assert len(list(self.db.select("bookshelves_books", where={
            "username": "@cdrini",
            "work_id": "2",
            "edition_id": "1"
        }))), "failed to update 1 to 2"
        assert not len(list(self.db.select("bookshelves_books", where={
            "username": "@cdrini",
            "work_id": "1",
            "edition_id": "1"
        }))), "old value 1 present"


class TestBooknotesUpdateWorkID:
    @classmethod
    def setup_class(cls):
        web.config.db_parameters = dict(dbn="sqlite", db=":memory:")
        db = get_db()
        db.query("""
            CREATE TABLE booknotes (
                username text NOT NULL,
                work_id integer NOT NULL,
                edition_id integer NOT NULL DEFAULT -1,
                notes text NOT NULL,
                PRIMARY KEY (username, work_id, edition_id)
            );
        """)

    def setup_method(self):
        self.db = get_db()
        self.db.insert("booknotes", username="alice", work_id=1,
                       edition_id=1, notes="source one")
        self.db.insert("booknotes", username="bob", work_id=1,
                       edition_id=2, notes="source two")

    def teardown_method(self):
        self.db.delete("booknotes", where="1=1")

    def notes(self):
        return sorted(
            (row.username, row.work_id, row.edition_id, row.notes)
            for row in self.db.select("booknotes")
        )

    def test_conflicting_primary_key_preserves_every_note(self):
        self.db.insert("booknotes", username="alice", work_id=2,
                       edition_id=1, notes="target")
        before = self.notes()

        assert Booknotes.update_work_id(1, 2) == {
            "rows_changed": 0, "rows_deleted": 0, "failed_deletes": 1
        }
        assert self.notes() == before

    def test_existing_target_without_primary_key_collision_blocks_update(self):
        self.db.insert("booknotes", username="charlie", work_id=2,
                       edition_id=3, notes="target")
        before = self.notes()

        assert Booknotes.update_work_id(1, 2) == {
            "rows_changed": 0, "rows_deleted": 0, "failed_deletes": 1
        }
        assert self.notes() == before

    def test_update_and_test_mode(self):
        before = self.notes()
        assert Booknotes.update_work_id(1, 2, _test=True) == {
            "rows_changed": 2, "rows_deleted": 0, "failed_deletes": 0
        }
        assert self.notes() == before

        assert Booknotes.update_work_id(1, 2) == {
            "rows_changed": 2, "rows_deleted": 0, "failed_deletes": 0
        }
        assert self.notes() == [
            ("alice", 2, 1, "source one"),
            ("bob", 2, 2, "source two"),
        ]

